params = {
    'backbone.conv1': True,
    'backbone.layer4': True,
    'head.fc': True,
}
for name in params:
    if name.startswith('backbone'):
        params[name] = False
n_trainable = sum(1 for v in params.values() if v)
print(n_trainable)

def choose_strategy(n_images):
    if n_images < 1000:
        return 'feature_extraction'
    return 'fine_tuning'

print(choose_strategy(300))
print(choose_strategy(5000))
